challenge.code:
const P = ctx.params;
const head = ctx.text('Button(  __  ,  {  __  })', { size: 14, mono: true, color: ctx.colors.g1 });
head.anchor.set(0.5); head.x = ctx.width / 2; head.y = 16;
ctx.stage.addChild(head);
const note = ctx.text('tap a lane to route the lowest token', { size: 11, mono: true, color: ctx.colors.dim });
note.anchor.set(0.5); note.x = ctx.width / 2; note.y = 36;
ctx.stage.addChild(note);
let score = 0, strikes = 0, t = 40;
const live = [];
ctx.api.setGoal('0 / ' + P.target);
function route(kind, d) {
  let best = null;
  for (let i = 0; i < live.length; i++) { if (!best || live[i].y > best.y) best = live[i]; }
  if (!best) return;
  live.splice(live.indexOf(best), 1);
  const lane = best.lane;
  best.destroy();
  gsap.to(d.scale, { x: 1.14, y: 1.14, duration: .1, onComplete: () => gsap.to(d.scale, { x: 1, y: 1, duration: .18, ease: 'back.out' }) });
  if (lane === kind) {
    score++;
    ctx.api.setScore(score);
    ctx.api.setGoal(score + ' / ' + P.target);
    note.text = kind === 'pos' ? 'bound to slot 1 - the label' : 'bound by name, order irrelevant';
    if (score >= P.target) ctx.api.win('Every token in the role that binds it. One call, one form.');
    return;
  }
  strikes++;
  if (lane === 'none' && kind === 'pos') note.text = 'onClick = "primary" - the button now does nothing';
  else if (lane === 'none') note.text = 'a bare string is not a key/value pair - let it fall';
  else if (kind === 'pos') note.text = 'that token carries a name - it belongs in the object';
  else note.text = 'the label is the positional slot, not a named prop';
  if (strikes >= 3) ctx.api.fail(note.text);
}
function dock(label, cx, kind) {
  const d = ctx.chip(label, { color: kind === 'pos' ? ctx.colors.g1 : ctx.colors.g2, textColor: 0x180b28, size: 12, minWidth: 140 });
  d.x = cx; d.y = ctx.height - 24;
  d.eventMode = 'static';
  d.cursor = 'pointer';
  d.on('pointertap', () => route(kind, d));
  ctx.stage.addChild(d);
  return d;
}
dock('positional', ctx.width * 0.27, 'pos');
dock('{ options }', ctx.width * 0.73, 'opt');
ctx.onTick((dt) => {
  t += dt;
  if (t > 54) {
    t = 0;
    const r = Math.random();
    const lane = r < 0.2 ? 'none' : (r < 0.46 ? 'pos' : 'opt');
    const tok = lane === 'none' ? P.trap : (lane === 'pos' ? P.positional : ctx.pick(P.options));
    const c = ctx.chip(tok, { color: ctx.colors.g3, textColor: 0x180b28, size: 12 });
    c.x = ctx.rand(90, ctx.width - 90);
    c.y = -18;
    c.lane = lane;
    ctx.stage.addChild(c);
    live.push(c);
  }
  for (let i = live.length - 1; i >= 0; i--) {
    const c = live[i];
    c.y += 1.45 * dt;
    if (c.y > ctx.height - 48) {
      live.splice(i, 1);
      if (c.lane === 'none') note.text = 'let it fall - a bare string has no slot here';
      c.destroy();
    }
  }
});

